(()=>{const reduce=matchMedia('(prefers-reduced-motion:reduce)'),sections=[...document.querySelectorAll('#community,.hardware,.manufacture,.logos,.testimonials,.faq')];document.querySelectorAll('.testimonials .story').forEach((el,i)=>el.style.setProperty('--story-i',i));let frame=0;function paint(){frame=0;for(const section of sections){const r=section.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight*1.15)continue;const raw=(innerHeight-r.top)/(innerHeight*.78);const p=reduce.matches?1:Math.max(0,Math.min(1,raw));section.style.setProperty('--lower-p',1-Math.pow(1-p,3))}}function queue(){if(!frame)frame=requestAnimationFrame(paint)}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);reduce.addEventListener('change',queue);paint()})();
